Translate("frFR", "razorfen-kraul", {
	title = "Kraal de Tranchebauge",
	aliases = { "le Kraal", "Kraal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Kraal de Tranchebauge est la grande garenne d'épines des {link:quilboar}hurans{/link} à la lisière sud des {link:the-barrens}Tarides{/link}, près de la frontière de {link:thousand-needles}Mille pointes{/link}. C'est un dédale de tranchées, de tunnels et de ponts tissés à travers des ronces si vastes qu'elles s'élèvent tout autour comme des murailles. Les hurans le tiennent pour sacré. C'est aussi une forteresse, et de nos jours le siège d'une vieille matrone qui entend faire siennes les Tarides du sud.]=],
		},
		{
			title = "Origines",
			text = [=[Il y a dix mille ans, pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, le demi-dieu {red:agamaggan}Agamaggan{/red} se dressa contre la {link:burning-legion}Légion ardente{/link}. Le grand sanglier tomba au combat. Son corps aplanit la terre où il mourut, et son sang s'enfonça dans le sol. Là où il tomba poussèrent des flèches d'épines tordues. Les hurans, qui se disent ses enfants, vinrent vivre parmi les épines et les nommèrent Tranchebauge. Le Kraal est l'une de leurs plus grandes places fortes.

Les elfes de la nuit se souviennent d'Agamaggan comme d'un être pur et généreux. Leurs druides ne savent dire pourquoi la terre autour de son lieu de repos est devenue si souillée, ni pourquoi les épines semblent répandre une corruption qui leur est propre.]=],
		},
		{
			title = "Le temps présent",
			text = [=[La vieille matrone {link:charlga-razorflank}Charlga Razorflank{/link} règne sur le Kraal. C'est une maîtresse de la magie de la terre, et elle rassemble une armée. Sous la poussée des hurans des {link:the-barrens}Tarides{/link} du sud, les taurens furent chassés de terres qu'ils tenaient depuis des générations, et ils ne l'ont pas oublié. Du Kraal vinrent les trois chefs Tranchecrins qui saignaient les lignes de ravitaillement de {link:the-crossroads}La Croisée{/link} depuis la {link:blackthorn-ridge}Crête de Noirépine{/link}.

On murmure pire encore. Une lettre prise à la matrone porte le sceau du {link:scourge}Fléau{/link}. Un émissaire des morts-vivants attend devant les {link:razorfen-downs}Souilles de Tranchebauge{/link}, l'autre grande garenne à l'est, et lui offre les Tarides et davantage en échange des mains libres. Ses guerriers parlent déjà de nouveaux alliés.

Peu d'étrangers sont entrés dans le Kraal et en sont ressortis. Un druide {link:night-elves}elfe de la nuit{/link} nommé {link:heralath-fallowbrook}Heralath{/link} et un {link:dwarves}nain{/link} de la {link:explorers-league}Ligue des explorateurs{/link} y furent traînés comme prisonniers. Un marchand gobelin vint chercher des tubercules rares et fut pris. L'alarme a désormais atteint {link:thalanaar}Thalanaar{/link}, {link:thunder-bluff}Thunder Bluff{/link} et même {link:undercity}Undercity{/link}.]=],
		},
		{
			title = "Au sein du Kraal",
			text = [=[• {b}Les tranchées.{/b} Des chemins sinueux sous les épines, où poussent les tubercules bleufeuilles et où les dresseurs de bêtes gardent leurs sangliers.
• {b}La salle du suzerain.{/b} Le suzerain {link:overlord-ramtusk}Ramtusk{/link} y commande l'armée, avec non loin le {link:death-speaker-jargba}Nécrorateur Jargba{/link} et le prophète {link:aggem-thorncurse}Aggem Thorncurse{/link}.
• {b}Les grottes aux chauves-souris.{/b} Des tunnels profonds pleins de chauves-souris du Kraal. Dans leurs profondeurs les plus sombres chasse une bête pâle qui n'a jamais vu le jour.
• {b}L'enclos.{/b} Un tunnel scellé par une barrière de magie hurane, où l'on garde {link:agathelos-the-raging}Agathelos le Déchaîné{/link}.
• {b}La hutte de {link:charlga-razorflank}la matrone{/link}.{/b} La demeure de Charlga se dresse en haut d'une rampe d'épines. En dessous, dans une petite hutte, se trouvent les prisonniers du Kraal.]=],
		},
	},
})

Translate("frFR", "charlga-razorflank", {
	title = "Charlga Razorflank",
	subtitle = "La matrone du Kraal",
	found = [=[Sa hutte au sommet des épines, dans les profondeurs du Kraal de Tranchebauge]=],
	hint = [=[Montez jusqu'à la hutte de la matrone qui règne sur le Kraal de Tranchebauge.]=],
	allegiance = "Hurans Tranchebauge",
	aliases = { "Razorflank", "la matrone du Kraal", "la matrone" },
	sections = {
		{
			title = "Résumé",
			text = [=[Charlga Razorflank est la matrone du Kraal de Tranchebauge, une hurane âgée et une puissante adepte de la magie de la terre. Elle gouverne la grande garenne depuis une hutte perchée parmi les épines. Sous son règne, les hurans du {link:razorfen-kraul}Kraal{/link} se sont enhardis. Ils attaquent les tribus rivales et les villages de la {link:horde}Horde{/link}, font des prisonniers et se préparent à la guerre. Elle dit siennes les terres qui entourent le Kraal, et elle traite chaque étranger en voleur.]=],
		},
		{
			title = "Importance",
			text = [=[Charlga est la puissance montante des {link:the-barrens}Tarides{/link} du sud. Les druides elfes de la nuit craignent que la corruption des épines ne se répande depuis son domaine. Les taurens de {link:thunder-bluff}Thunder Bluff{/link} tiennent son peuple pour responsable de les avoir chassés de leur terre sacrée. Et le {link:scourge}Fléau{/link} l'a approchée pour en faire une alliée en {link:kalimdor}Kalimdor{/link}. A-t-elle accepté son offre ? Nul hors du {link:razorfen-kraul}Kraal{/link} ne saurait le dire.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle prit {link:razorfen-kraul}le Kraal{/link} et rassembla les hurans sous son autorité.
• Ses guerriers capturèrent le druide {link:heralath-fallowbrook}Heralath{/link} et le {link:dwarves}nain{/link} Henrig Lonebrow.
• Elle reçut des lettres de l'émissaire du {link:scourge}Fléau{/link} {link:ambassador-malcin}Malcin{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'avertissement",
			hint = "Portez à Thalanaar l'avertissement d'un nain mort.",
			text = [=[Henrig Lonebrow s'échappa du {link:razorfen-kraul}Kraal{/link} avec un avertissement pour {link:falfindel-waywarder}Falfindel Waywarder{/link} à {link:thalanaar}Thalanaar{/link} : la matrone soulevait ses sbires, et sa puissance grandissait de jour en jour. Le {link:dwarves}nain{/link} mourut avant de pouvoir le transmettre. Son journal fit le travail à sa place. Falfindel envoya d'autres mettre fin à la vie de la matrone, et espéra qu'une fois celle-ci disparue, son peuple apprendrait ce qui avait corrompu le lieu de repos d'Agamaggan.]=],
		},
		{
			title = "Une vengeance",
			hint = "Répondez à l'ancien tauren qui ne peut pardonner.",
			text = [=[{red:auld-stonespire}Auld Stonespire{/red} de {link:thunder-bluff}Thunder Bluff{/link} honore {link:cairne-bloodhoof}Cairne Bloodhoof{/link} pour avoir uni les taurens, mais il ne peut pardonner à ceux qui chassèrent son peuple des {link:the-barrens}Tarides{/link} du sud. Il demanda le cœur de la matrone. Quand il lui parvint, il dit que les hurans du {link:razorfen-kraul}Kraal{/link} connaissaient désormais la douleur de son peuple.]=],
		},
		{
			title = "La lettre de l'émissaire",
			hint = "Cherchez ce que la matrone garde sur elle.",
			text = [=[On trouva sur la matrone un petit parchemin. Il était signé de l'ambassadeur {link:ambassador-malcin}Malcin{/link}, qui lui promettait les {link:the-barrens}Tarides{/link} et davantage en échange de la liberté d'y agir. {link:varimathras}Varimathras{/link} reconnut aussitôt le sceau. Il jugea que la matrone n'avait pas encore cédé, peut-être parce qu'elle sentait que les Tarides ne seraient jamais vraiment à elle avec de tels alliés.]=],
		},
	},
	mentions = {
		{ text = "Le journal de Lonebrow" },
		{ text = "Une alliance impie" },
	},
	bonds = {
		{ id = "overlord-ramtusk", name = "Suzerain Ramtusk", note = "commande ses guerriers" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "son prisonnier" },
		{ id = "varimathras", name = "Varimathras", note = "lut la lettre qu'elle gardait" },
	},
})

Translate("frFR", "overlord-ramtusk", {
	title = "Suzerain Ramtusk",
	subtitle = "Seigneur de guerre du Kraal",
	found = [=[La salle de guerre du Kraal de Tranchebauge, flanqué de ses gardes]=],
	hint = [=[Affrontez le vieux seigneur de guerre qui commande l'armée du Kraal.]=],
	allegiance = "Hurans Tranchebauge",
	aliases = { "Ramtusk" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le suzerain Ramtusk commande les guerriers du {link:razorfen-kraul}Kraal de Tranchebauge{/link}. C'est un {link:quilboar}huran{/link} vieux et massif. On dit que son cuir porte les cicatrices de combats contre les centaures, les harpies, les orcs et les taurens, et que l'âge ne l'a nullement ralenti. Deux gardes peau-de-lance se tiennent à ses côtés et mourraient pour lui. Il va au combat le nom d'Agamaggan aux lèvres.]=],
		},
		{
			title = "Importance",
			text = [=[Ramtusk est l'épée de {link:charlga-razorflank}la matrone{/link}. L'armée qu'elle rassemble lui obéit, et ce sont ses guerriers qui porteront sa guerre dans les {link:the-barrens}Tarides{/link} si personne ne les arrête avant.]=],
		},
		{ title = "Hauts faits", text = "• Il mène l'armée du {link:razorfen-kraul}Kraal{/link}." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "sa maîtresse" },
		{ id = "death-speaker-jargba", name = "Nécrorateur Jargba", note = "maintient ses guerriers dans l'obéissance" },
	},
})

Translate("frFR", "death-speaker-jargba", {
	title = "Nécrorateur Jargba",
	subtitle = "Capitaine de la Tête de mort",
	found = "Près de la salle de guerre du Kraal de Tranchebauge",
	hint = "Affrontez le huran qui annonce le retour du dieu mort.",
	allegiance = "Hurans Tranchebauge · Tête de mort",
	aliases = { "Jargba" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Nécrorateur Jargba est un capitaine de la {link:death-s-head}Tête de mort{/link}, l'ordre sombre qui s'est répandu parmi les hurans de Tranchebauge. Les nécrorateurs sont à la fois prêtres et guerriers. Ils prêchent qu'Agamaggan, tombé, se relèvera, et ils punissent ceux qui refusent d'obéir à {link:charlga-razorflank}la matrone{/link}. On dit que Jargba plie l'esprit de ses ennemis comme celui des dissidents de son propre camp, et qu'il manie l'ombre comme une arme.]=],
		},
		{
			title = "Importance",
			text = [=[Jargba montre combien la foi du {link:razorfen-kraul}Kraal{/link} s'est détournée du dieu pur qu'elle prétend servir.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il prêche le retour d'Agamaggan parmi les guerriers du {link:razorfen-kraul}Kraal{/link}.]=],
		},
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "la matrone qu'il sert" },
		{ id = "aggem-thorncurse", name = "Aggem Thorncurse", note = "un frère de la Tête de mort" },
	},
})

Translate("frFR", "aggem-thorncurse", {
	title = "Aggem Thorncurse",
	subtitle = "Prophète de la Tête de mort",
	found = "Les salles du Kraal de Tranchebauge",
	hint = [=[Affrontez le prophète du Kraal qui invoque des esprits de sanglier.]=],
	allegiance = "Hurans Tranchebauge · Tête de mort",
	aliases = { "Thorncurse" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aggem Thorncurse est un prophète de la {link:death-s-head}Tête de mort{/link}. Chez les hurans, les plus grands chamans sont appelés prophètes d'Agamaggan. Ils font appel à la puissance de leur ancêtre pour invoquer des esprits de sanglier à leurs côtés, comme d'autres chamans appellent des loups spirituels. Aggem le fait pour défendre {link:razorfen-kraul}le Kraal{/link}, et un sanglier spirituel combat à ses côtés quand il est menacé.]=],
		},
		{
			title = "Importance",
			text = [=[Aggem porte à la fois le nom du dieu sanglier et le titre de l'ordre sombre. En lui, le vieux chamanisme des hurans et le nouveau credo de la {link:death-s-head}Tête de mort{/link} ne font plus qu'un.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il appelle des sangliers spirituels pour défendre {link:razorfen-kraul}le Kraal{/link}.]=],
		},
	},
	bonds = {
		{ id = "death-speaker-jargba", name = "Nécrorateur Jargba", note = "un frère de la Tête de mort" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "la matrone qu'il sert" },
	},
})

Translate("frFR", "roogug", {
	title = "Roogug",
	subtitle = "Géomancien du Kraal",
	found = "Les premières tranchées du Kraal de Tranchebauge",
	hint = [=[Affrontez le géomancien qui garde les premières tranchées du Kraal.]=],
	allegiance = "Hurans Tranchebauge",
	sections = {
		{
			title = "Résumé",
			text = [=[Roogug est un géomancien du {link:razorfen-kraul}Kraal de Tranchebauge{/link} qui garde les premières tranchées derrière sa porte. Comme {link:charlga-razorflank}la matrone{/link} qu'il sert, il puise dans la puissance de la terre. Il lance la foudre et appelle une pierre vivante à combattre à ses côtés. Il porte aussi une fiole de phlogiston, une rare substance ignée que les forgerons de l'{link:alliance}Alliance{/link} comme de la {link:horde}Horde{/link} recherchent pour forger des cottes de mailles durcies.]=],
		},
		{
			title = "Importance",
			text = [=[Roogug est le premier des mystiques de {link:charlga-razorflank}la matrone{/link} que rencontre tout intrus.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde les tranchées de l'ouest par la magie de la terre.]=],
		},
	},
	mentions = {
		{ text = "Cotte de mailles durcie au feu" },
		{ text = "Armure brutale" },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "la matrone qu'il sert" },
	},
})

Translate("frFR", "agathelos-the-raging", {
	title = "Agathelos le Déchaîné",
	subtitle = "Le sanglier en cage",
	found = [=[Un tunnel scellé au-delà des grottes aux chauves-souris du Kraal de Tranchebauge]=],
	hint = [=[Cherchez le grand sanglier que les hurans gardent derrière leur barrière.]=],
	allegiance = "Aucune",
	aliases = { "Agathelos" },
	sections = {
		{
			title = "Résumé",
			text = [=[Agathelos le Déchaîné est un sanglier cuirassé colossal gardé dans un tunnel du {link:razorfen-kraul}Kraal de Tranchebauge{/link}. Des gardiens hurans le retiennent derrière une barrière magique. Pour un peuple qui appelle un grand sanglier son dieu, une telle bête n'est pas un animal ordinaire : on dit qu'ils voient en un sanglier puissant un don d'Agamaggan. On dit aussi qu'on l'a nourri du guano des chauves-souris du Kraal, qui le rend fou et plus fort encore, et que la {link:death-s-head}Tête de mort{/link} entend le lâcher sur ses ennemis.]=],
		},
		{
			title = "Importance",
			text = [=[Agathelos est une arme que l'on prépare, un écho vivant du dieu que révère {link:razorfen-kraul}le Kraal{/link}.]=],
		},
		{ title = "Hauts faits", text = "• Il enrage dans son enclos, et grandit dans sa fureur." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "sa gardienne" },
	},
})

Translate("frFR", "blind-hunter", {
	title = "Chasseur aveugle",
	subtitle = "La chauve-souris pâle des profondeurs",
	found = [=[Les grottes aux chauves-souris les plus sombres du Kraal de Tranchebauge]=],
	hint = [=[Fouillez les grottes aux chauves-souris les plus profondes du Kraal à la recherche d'un chasseur pâle.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Chasseur aveugle est une grande chauve-souris pâle qui hante les grottes les plus profondes du {link:razorfen-kraul}Kraal de Tranchebauge{/link}. On la voit rarement, même parmi les hurans. Elle vit là où aucune lumière ne parvient, et elle semble n'avoir nul besoin d'yeux. Les chauves-souris du Kraal, plus petites, nichent plus près de l'entrée des tunnels. Leurs déjections sont si rares que la {link:royal-apothecary-society}Société royale des apothicaires{/link} d'{link:undercity}Undercity{/link} en a fait demander.]=],
		},
		{
			title = "Importance",
			text = [=[Le Chasseur aveugle est la plus ancienne terreur des lieux obscurs du {link:razorfen-kraul}Kraal{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il chasse dans les profondeurs des grottes aux chauves-souris.]=],
		},
	},
	mentions = {
		{ text = "Une fois, deux fois, guano !" },
	},
})

Translate("frFR", "earthcaller-halmgar", {
	title = "Mande-terre Halmgar",
	subtitle = "Mande-terre du Kraal",
	found = [=[Au-delà de la salle de guerre du Kraal de Tranchebauge, après les ponts de bois]=],
	hint = [=[Cherchez la rare mande-terre qui erre sur les ponts du Kraal.]=],
	allegiance = "Hurans Tranchebauge",
	aliases = { "Halmgar" },
	sections = {
		{
			title = "Résumé",
			text = [=[La mande-terre Halmgar est une mystique hurane du {link:razorfen-kraul}Kraal de Tranchebauge{/link}, l'une des façonneuses de terre que {link:charlga-razorflank}la matrone{/link} a rassemblées. On la trouve rarement. Quand on la trouve, elle fait tomber la foudre sur ses ennemis, les cloue au sol avec un totem et invoque une pierre vivante pour les écraser. Les mande-terre sont la raison pour laquelle les épines du Kraal sont si difficiles à prendre d'assaut.]=],
		},
		{
			title = "Importance",
			text = [=[Halmgar montre la profondeur de la magie de la terre que commande {link:charlga-razorflank}la matrone{/link}. Là où marchent ses mystiques, le sol même du {link:razorfen-kraul}Kraal{/link} combat pour les hurans.]=],
		},
		{ title = "Hauts faits", text = "• Elle garde les chemins au-delà de la salle de guerre." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "la matrone qu'elle sert" },
	},
})

Translate("frFR", "willix-the-importer", {
	title = "Willix l'Importateur",
	subtitle = "Entrepreneur gobelin",
	found = [=[Une hutte au pied de la rampe de la matrone, dans le Kraal de Tranchebauge]=],
	hint = [=[Cherchez le prisonnier gobelin retenu dans les profondeurs du Kraal.]=],
	allegiance = "Ratchet · Cartel Gentepression",
	aliases = { "Willix" },
	sections = {
		{
			title = "Résumé",
			text = [=[Willix est un marchand gobelin de {link:ratchet}Ratchet{/link}, toujours à l'affût d'une pièce de cuivre. Il avait entendu dire que Mebok Mizzyrix payait bien les tubercules rares qui poussent dans {link:razorfen-kraul}le Kraal{/link}, et il pensait que ce serait un travail facile. Les hurans le prirent. Il fut retenu si longtemps qu'il oublia quand il avait vu le ciel pour la dernière fois. Même prisonnier, il ne perdait pas de vue le profit : les tubercules des tranchées, dit-il, sont de l'or qui n'attend que d'être déterré.]=],
		},
		{
			title = "Importance",
			text = [=[Willix prouve que {link:razorfen-kraul}le Kraal{/link} est une prison autant qu'une forteresse.]=],
		},
	},
	chapters = {
		{
			title = "Hors des épines",
			hint = "Guidez le prisonnier gobelin hors du Kraal.",
			text = [=[On mena Willix à travers les tranchées et en haut des ronces, tandis qu'il criait des avertissements à chaque {link:quilboar}huran{/link} qui chargeait. En passant devant la hutte de {link:charlga-razorflank}la matrone{/link}, il la maudit, cette satanée vieille matrone. Enfin, il se retrouva libre, reprit son souffle et partit pour {link:ratchet}Ratchet{/link}.]=],
		},
	},
	mentions = {
		{ text = "Tubercules bleufeuilles" },
	},
	bonds = {
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "un compagnon de captivité" },
	},
})

Translate("frFR", "heralath-fallowbrook", {
	title = "Heralath Fallowbrook",
	subtitle = "Druide de Darnassus",
	found = [=[Une hutte de prisonniers dans les profondeurs du Kraal de Tranchebauge]=],
	hint = [=[Cherchez l'elfe de la nuit blessé retenu captif dans le Kraal.]=],
	allegiance = "Elfes de la nuit · Darnassus",
	aliases = { "Heralath" },
	sections = {
		{
			title = "Résumé",
			text = [=[Heralath Fallowbrook est un druide {link:night-elves}elfe de la nuit{/link} venu dans les {link:the-barrens}Tarides{/link} du sud pour découvrir la vérité sur le dieu sanglier tombé. Il croyait que le grand crâne des plaines marquait le lieu où Agamaggan était tombé, et son peuple voulait savoir pourquoi le lieu de repos d'un être si pur s'était corrompu. Les hurans le prirent, le fouettèrent et le jetèrent dans une hutte du {link:razorfen-kraul}Kraal{/link}. Il y partagea sa cellule avec le {link:dwarves}nain{/link} {red:henrig-lonebrow}Henrig Lonebrow{/red}, et lui confia un avertissement pour {link:falfindel-waywarder}Falfindel Waywarder{/link}.]=],
		},
